const a=$input.all().map(i=>i.json).filter(x=>x&&Object.keys(x).length);
if(a.some(x=>x.error))return [{json:{readable:false,activeCount:0,reason:'ESPOCRM_UNAVAILABLE'}}];
const keys=new Set();
for(const c of a){if(!c.id||keys.has(c.id))throw new Error('DUPLICATE_ESPO_CAMPAIGN_ID');keys.add(c.id);}
return [{json:{readable:true,count:a.length,activeCount:a.filter(x=>x.status==='Active').length,
 chatwootConfigured:a.filter(x=>String(x.ageProvider||'').includes('Chatwoot')).length}}];

const a=$input.all().map(i=>i.json).filter(x=>x&&Object.keys(x).length);
if(a.some(x=>x.error))return [{json:{readable:false,reason:'CHATWOOT_UNAVAILABLE'}}];
const keys=new Set();
for(const c of a){const id=Number(c.id);if(!Number.isSafeInteger(id)||keys.has(id))throw new Error('INVALID_OR_DUPLICATE_CHATWOOT_ID');keys.add(id);}
return [{json:{readable:true,count:a.length,nativeWhatsApp:a.filter(c=>c.campaign_type==='one_off'&&c.inbox?.channel_type==='Channel::Whatsapp').length}}];

const crm=$('Count Espo Campaigns').first().json;
const provider=$('Count Native Chatwoot Campaigns').first().json;
const control=$input.all().map(i=>i.json).filter(x=>x&&Object.keys(x).length);
const reasons=[];
if(!crm.readable)reasons.push('ESPOCRM_NOT_READABLE');
if(!provider.readable)reasons.push('CHATWOOT_NOT_READABLE');
if(control.some(x=>x.error))reasons.push('N8N_DATA_TABLE_UNAVAILABLE');
if(!control.length)reasons.push('NO_PORTFOLIO_RECORDS');
if(control.length>50)reasons.push('TOO_MANY_PORTFOLIOS');
const seen=new Set(),now=Date.now(),p=[];
for(const row of control.filter(x=>x.portfolioId)){
 const id=String(row.portfolioId);
 if(seen.has(id))reasons.push('DUPLICATE_PORTFOLIO_ID');seen.add(id);
 const holds=[];
 if(row.masterSendingEnabled!==true)holds.push('MASTER_DISABLED');
 if(row.operatorLiveApproved!==true)holds.push('OPERATOR_NOT_APPROVED');
 if(row.unresolvedCycle!==false||row.activeCycleId)holds.push('UNRESOLVED_CYCLE');
 if(row.externalUsageUnknown!==false)holds.push('EXTERNAL_USAGE_UNKNOWN');
 const t=Date.parse(row.lastVerifiedBatchCompletedAt);
 if(row.lastVerifiedBatchCompletedAt&&(!Number.isFinite(t)||now-t<26*3600000))holds.push('GLOBAL_26_HOUR_GAP');
 holds.push('NO_ATOMIC_RESERVATION_GATE','RECIPIENT_CONSENT_NOT_VERIFIED');
 p.push({portfolioId:id,holds});
}
return [{json:{checkedAt:new Date().toISOString(),mode:'DRY_RUN',decision:'HOLD',
 espoCampaignCount:crm.count??0,activeEspoCampaigns:crm.activeCount??0,
 chatwootCampaignCount:provider.count??0,portfolio:p,
 reasons:[...new Set([...reasons,'META_PORTFOLIO_CAPACITY_NOT_VERIFIED','NO_PRODUCTION_SENDING_GATE'])],
 canSend:false,createdCampaigns:0,crmEventsWritten:0}}];
